 11	@Entity
 12	@Getter
 13	@NoArgsConstructor
 14	@AllArgsConstructor
 15	@Builder
 16	public class OrderShipment extends BaseTimeEntity {
 17	
 18	    @Id
 19	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 20	    private Long id;
 21	
 22	    @OneToOne(fetch = FetchType.LAZY)
 23	    @JoinColumn(name = "order_id", nullable = false)
 24	    private Order order;
 25	
 26	    private String receiverName; // 수령인 이름
 27	    private String receiverPhone; // 수령인 전화번호
 28	    private String postalCode; // 우편번호
 29	    private String address; // 주소
 30	    private String courier; // 택배사 이름
 31	    private String trackingNumber; // 송장 번호
 32	
 33	    @Enumerated(EnumType.STRING)
 34	    private ShipmentStatus status;
 35	
 36	
 37	    public void assignOrder(Order order) {
 38	        this.order = order;
 39	    }
 40	
 41	    public void updateTrackingInfo(String courier, String trackingNumber) {
 42	        this.courier = courier;
 43	        this.trackingNumber = trackingNumber;
 44	        this.status = ShipmentStatus.IN_TRANSIT;
 45	    }
 46	
 47	    public void updateStatus(ShipmentStatus newStatus) {
 48	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
 49	            this.status = newStatus;
 50	        } else {
 51	            throw new IllegalStateException(
 52	                    "Cannot transition from " + this.status + " to " + newStatus
 53	            );
 54	        }
 55	    }
 56	}
  1	package com.fream.back.domain.shipment.entity;
  2	
  3	public enum ShipmentStatus {
  4	    PENDING {
  5	        @Override
  6	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
  7	            return nextStatus == SHIPPED || nextStatus == CANCELED;
  8	        }
  9	    },
 10	    SHIPPED {
 11	        @Override
 12	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 13	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
 14	        }
 15	    },
 16	    IN_TRANSIT {
 17	        @Override
 18	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 19	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
 20	                    || nextStatus == DELIVERED;
 21	        }
 22	    },
 23	    OUT_FOR_DELIVERY {
 24	        @Override
 25	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 26	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
 27	        }
 28	    },
 29	    DELIVERED {
 30	        @Override
 31	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 32	            return false; // 배송 완료 이후로는 상태 전환 없음
 33	        }
 34	    },
 35	    RETURNED {
 36	        @Override
 37	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 38	            return nextStatus == CANCELED;
 39	        }
 40	    },
 41	    CANCELED {
 42	        @Override
 43	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 44	            return false; // 취소 이후 상태 전환 없음
 45	        }
 46	    },
 47	    DELAYED {
 48	        @Override
 49	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 50	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
 51	        }
 52	    },
 53	    FAILED_DELIVERY {
 54	        @Override
 55	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 56	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
 57	        }
 58	    };
 59	
 60	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
 61	}
