185	    /**
186	     * 주문을 완료 상태로 변경하고 관련된 후속 작업을 처리합니다.
187	     *
188	     * @param orderId 완료할 주문 ID
189	     */
190	    @Transactional
191	    public void completeOrder(Long orderId) {
192	        log.info("주문 완료 처리 시작: orderId={}", orderId);
193	
194	        try {
195	            // OrderBid 조회
196	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
197	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
198	
199	            Order order = orderBid.getOrder();
200	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
201	                    order.getId(), order.getUser().getId(), order.getStatus());
202	
203	            // 주문 상태를 COMPLETED로 변경
204	            order.updateStatus(OrderStatus.COMPLETED);
205	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
206	
207	            // 판매 상태 변경 로직
208	            updateSaleStatusToSold(orderId);
209	
210	            // 주문 완료 알림
211	            User buyer = order.getUser();
212	            notificationCommandService.createNotification(
213	                    buyer.getId(),
214	                    NotificationCategory.SHOPPING,
215	                    NotificationType.BID,
216	                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
217	            );
218	
219	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
220	
221	        } catch (Exception e) {
222	            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
223	            throw new ShipmentException(
224	                    ShipmentErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
225	                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
226	                    e
227	            );
228	        }
229	    }
230	
231	    /**
232	     * 배송 정보에 운송장 정보를 업데이트하고 관련 상태를 변경합니다.
233	     *
234	     * @param shipmentId 배송 ID
235	     * @param courier 택배사 이름
236	     * @param trackingNumber 운송장 번호
237	     */
238	    @Transactional
239	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
240	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
241	                shipmentId, courier, trackingNumber);
242	
243	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
244	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
245	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
246	        }
247	
248	        try {
249	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
250	                    .orElseThrow(() -> new ShipmentException(
251	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
252	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
253	                    ));
254	
255	            // 운송장 정보 업데이트
256	            shipment.updateTrackingInfo(courier, trackingNumber);
257	
258	            // 배송 상태가 변경되었으므로 주문 상태도 업데이트
259	            Order order = shipment.getOrder();
260	            order.updateStatus(OrderStatus.IN_TRANSIT);
261	
262	            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());
263	
264	            // 주문한 사용자에게 알림 생성
265	            User buyer = order.getUser();
266	            notificationCommandService.createNotification(
267	                    buyer.getId(),
268	                    NotificationCategory.SHOPPING,
269	                    NotificationType.BID,
270	                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
271	            );
272	
273	            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());
274	
275	            // 판매 상태 업데이트 및 알림 전송
276	            updateSaleStatusToSold(order.getId());
277	
278	            // SaleBid에서 Sale 조회 및 창고 상태 업데이트
279	            SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
280	            if (saleBid != null) {
281	                Sale sale = saleBid.getSale();
282	                if (sale != null && sale.isWarehouseStorage()) {
283	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
284	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
285	                }
286	            }
287	
288	            // OrderBid 상태를 COMPLETED로 변경
289	            updateOrderAndSaleBidStatusToCompleted(order.getId());
290	
291	            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
292	
293	        } catch (ShipmentException e) {
294	            throw e;
295	        } catch (Exception e) {
296	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
297	            throw new ShipmentException(
298	                    ShipmentErrorCode.SHIPMENT_NOT_FOUND,
299	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
300	                    e
301	            );
302	        }
303	    }
304	
305	    /**
306	     * 전체 배송 상태를 주기적으로 업데이트합니다.
307	     */
308	    @Transactional
309	    public void updateShipmentStatuses() {
310	        log.info("전체 배송 상태 업데이트 시작");
311	
312	        // 1. IN_TRANSIT 또는 OUT_FOR_DELIVERY 상태의 OrderShipment 조회
313	        List<OrderShipment> shipments = orderShipmentRepository.findByStatusIn(
314	                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
315	        );
316	
317	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
318	
319	        int successCount = 0;
320	        int errorCount = 0;
321	
322	        for (OrderShipment shipment : shipments) {
323	            try {
324	                String trackingNumber = shipment.getTrackingNumber();
325	                if (trackingNumber == null || trackingNumber.isBlank()) {
326	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
327	                    errorCount++;
328	                    continue;
329	                }
330	
331	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
332	                        shipment.getId(), trackingNumber);
333	
334	                // 2. CJ대한통운에서 현재 배송 상태 추출
335	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
336	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
337	
338	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
339	                        shipment.getId(), currentStatus, newStatus);
340	
341	                // 현재 상태와 동일한 경우 중복 처리 방지
342	                if (shipment.getStatus() == newStatus) {
343	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
344	                            shipment.getId(), newStatus);
345	                    successCount++;
346	                    continue;
347	                }
348	
349	                // 3. 배송 상태가 DELIVERED인 경우 Order와 Shipment 상태 업데이트
350	                if (newStatus == ShipmentStatus.DELIVERED) {
351	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
352	
353	                    shipment.updateStatus(newStatus);
354	                    Order order = shipment.getOrder();
355	                    order.updateStatus(OrderStatus.COMPLETED);
356	
357	                    // 배송 완료 알림 전송
358	                    User buyer = order.getUser();
359	                    notificationCommandService.createNotification(
360	                            buyer.getId(),
361	                            NotificationCategory.SHOPPING,
362	                            NotificationType.BID,
363	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
364	                    );
365	
366	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
367	                            buyer.getId(), order.getId());
368	
369	                } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY &&
370	                        shipment.getStatus() != ShipmentStatus.OUT_FOR_DELIVERY) {
371	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
372	                    shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
373	
374	                } else {
375	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
376	                            shipment.getId(), newStatus);
377	                    shipment.updateStatus(newStatus);
378	                }
379	
380	                orderShipmentRepository.save(shipment);
381	                successCount++;
382	
383	            } catch (Exception e) {
384	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
385	                        shipment.getId(), e.getMessage(), e);
386	                errorCount++;
387	            }
388	        }
389	
390	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
391	    }
392	
393	    /**
394	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
395	     *
396	     * @param statusText 배송사 상태 텍스트
397	     * @return 매핑된 ShipmentStatus
398	     */
399	    private ShipmentStatus mapToShipmentStatus(String statusText) {
400	        return switch (statusText) {
401	            case "배송완료" -> ShipmentStatus.DELIVERED;
402	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
403	            default -> ShipmentStatus.IN_TRANSIT;
404	        };
405	    }
406	
407	    /**
408	     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
409	     *
410	     * @param orderId 주문 ID
411	     */
412	    @Transactional
413	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
414	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
415	
416	        try {
417	            // OrderBid 조회
418	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
419	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
420	
421	            // 상태를 COMPLETED로 업데이트
